"""
    Check if a character is valid in xml.
    :param c: Input character.
    :return: True or False.
    """
def valid_xml_char_ordinal(c: Any) -> object {
    codepoint = ord(c);
    return (
        (32 <= codepoint <= 55295)
        or (codepoint in (9, 10, 13))
        or (57344 <= codepoint <= 65533)
        or (65536 <= codepoint <= 1114111)
    );
}

"""
    Given a JSON Schema compatible dict, returns True when the schema implements `$ref`

    NOTE: `$ref` OVERRIDES all other keys present in a schema
    :param schema:
    :return: Boolean
    """
def _is_ref(schema: Any) -> object {
    return ('$ref' in schema);
}

"""Generates a two digit string based on a provided string

    Args:
        rule_name (str): A configured rule name 'pytest_mark3'.

    Returns:
        str: A two digit code based on the provided string '03'
    """
def _generate_mark_code(rule_name: Any) -> object {
    code = ''.join(
        [
            i
            for i in str(rule_name)
            if i.isdigit()
        ]
    );
    code = code.zfill(2);
    return code;
}

"""
    Helper method to remove current ap from neighboring aps and return
    list of neighboring ap ids
    """
def get_neighboring_ap_ids(
    current_ap_location: Any, neighboring_aps: Any, location_to_ap_lookup: Any
) -> object {
    neighboring_ap_ids = [];
    if isinstance(current_ap_location, `list) {
        current_ap_location = `tuple(current_ap_location);
    }
    for ap_location in neighboring_aps {
        if (current_ap_location != ap_location) {
            neighboring_ap_ids.append(location_to_ap_lookup[ap_location]);
        }
    }
    return neighboring_ap_ids;
}

"""removes useless points from a path and leaves only turn-points"""
def compress_path(path: Any) -> object {
    new_path = path;
    i = 0;
    while (i < (len(new_path) - 2)) {
        (x1, y1) = new_path[i];
        (x2, y2) = new_path[(i + 1)];
        (x3, y3) = new_path[(i + 2)];
        if (((x1 == x2) and (x2 == x3)) or ((y1 == y2) and (y2 == y3))) {
            new_path.pop((i + 1));
        } else {
            i = i + 1;
        }
    }
    return new_path;
}

